import{z as r,x as A,o as l,c as p,q as B,j as o,D as E,d as n,s as t,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"现金持有","description":"","frontmatter":{"title":"现金持有","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cash-holdings.md","filePath":"econ/cash-holdings.md","lastUpdated":1791063341000}'),d={name:"econ/cash-holdings.md"};function m(C,a,h,D,c,F){const i=A("Mermaid");return l(),p("div",null,[a[2]||(a[2]=B('<h1 id="现金持有" tabindex="-1">现金持有 <a class="header-anchor" href="#现金持有" aria-label="Permalink to &quot;现金持有&quot;">​</a></h1><div class="epigraph"><p>现金是对冲与优序的存量替代：预防性余额避免昂贵的外部融资，也是 Jensen 的弹药；最优持有在流动性收益与代理成本之间。</p><footer>—— Opler, Pinkowitz, Stulz and Williamson, Journal of Financial Economics 1999；Almeida, Campello and Weisbach, Journal of Finance 2004；Keynes 的预防性动机在企业侧的改写</footer></div><p><a href="/econ/corporate-hedging-rationale">上一课</a>给出衍生品对冲。本课缺口是更简单的工具：持有现金与等价物。Opler 等把决定因素写成规模、机会、现金流风险、融资约束。Almeida–Campello–Weisbach：约束企业的现金对现金流敏感。不重做 FSS 的状态挪移公式，不把超额现金的治理写成并购全文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>营运资本课的经营现金是生产技术；本课是超额流动性。优序：囤现金以免将来走柠檬市场。FSS：现金是未对冲风险的缓冲。Jensen：成熟企业现金是浪费。三种理论对同一科目符号不同。缺口是按融资约束与投资机会分类，而不是「现金为王」一句。动态权衡：现金是负债，降杠杆，可以是带内的被动积累（盈利未派息），也可以是主动预防。</p><p><span class="marginnote">现金–现金流敏感性：约束企业在现金流入时多存，非约束企业不存。Almeida 等把它当融资约束度量，识别争议留给最后一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>权衡：流动性收益（避免发行成本、积压、展期失败）对税（利息在公司税与个人税下可能不利）、代理、以及机会成本（现金赚 \\(r_f\\) 而非 \\(r_U\\)）。与对冲替代：衍生品把特定风险挪开，现金对冲不可交易的综合缺口。信贷额度是或有现金，银行关系课已说明额度在危机中可能不可提——承诺现金仍有价值。</p><p><span class="marginnote">信贷额度可以想象成一张「可能刷不出的信用卡」：平时它是或有现金，几乎不要钱；危机来临时银行自己也缺钱，可能拒绝放款。所以账面上有额度不等于有现金，预防性余额才是真正握在手里的保险——两者事前像替代品，事后并不完全。</span></p><p>资本预算：项目若消耗预防性现金，要按机会成本计，不是零。国家风险下，可兑换现金与被困现金不同，\\(\\lambda\\) 再出现。</p>',10)),(l(),o(s,null,{default:E(()=>[t(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PO%5B%22%E4%BC%98%E5%BA%8F%20%2F%20FSS%22%5D%20--%3E%20HOLD%5B%22%E9%A2%84%E9%98%B2%E6%80%A7%E6%8C%81%E6%9C%89%22%5D%0A%20%20JENS%5B%22FCF%20%E4%BB%A3%E7%90%86%22%5D%20--%3E%20WASTE%5B%22%E6%B5%AA%E8%B4%B9%20%2F%20%E4%BD%8E%E5%9B%9E%E6%8A%A5%E5%B9%B6%E8%B4%AD%22%5D%0A%20%20HEDGE%5B%22%E8%A1%8D%E7%94%9F%E5%93%81%22%5D%20--%3E%20SUB%5B%22%E9%83%A8%E5%88%86%E6%9B%BF%E4%BB%A3%E7%8E%B0%E9%87%91%22%5D%0A%20%20LINE%5B%22%E4%BF%A1%E8%B4%B7%E9%A2%9D%E5%BA%A6%22%5D%20--%3E%20UNCOM%5B%22%E5%8D%B1%E6%9C%BA%E4%B8%AD%E5%8F%AF%E8%83%BD%E4%B8%8D%E5%8F%AF%E6%8F%90%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"派息与回购是把现金吐出的治理；激进主义常要求这一点。双层与家族可能把现金留在控制人可及之处。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是外部融资的状态依存成本。高成本状态（危机、低 M/B、评级悬崖）的影子价格高，事前持有现金是买保险。MM 无关性在有发行成本时失败，现金结构有关。被动积累：动态权衡带内利润变成现金，看起来像优序，其实是调整成本。",-1)),(l(),o(s,null,{default:E(()=>[t(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A6%81%E4%B8%8D%E8%A6%81%E5%A4%9A%E7%95%99%201%20%E5%85%83%E7%8E%B0%E9%87%91%EF%BC%9F%22%5D%20--%3E%20N%5B%22%E5%B9%B3%E6%97%B6%EF%BC%9A%E5%8F%AA%E8%B5%9A%20r_f%EF%BC%8C%E4%BB%98%E5%87%BA%E6%9C%BA%E4%BC%9A%E6%88%90%E6%9C%AC%22%5D%0A%20%20N%20--%3E%20C%5B%22%E5%8D%B1%E6%9C%BA%EF%BC%9A%E5%A4%96%E9%83%A8%E8%9E%8D%E8%B5%84%E8%B4%B5%E7%94%9A%E8%87%B3%E4%B8%8D%E5%8F%AF%E5%BE%97%22%5D%0A%20%20C%20--%3E%20S%5B%22%E6%89%8B%E5%A4%B4%E7%8E%B0%E9%87%91%E8%AE%A9%E6%8A%95%E8%B5%84%E4%B8%8D%E4%B8%AD%E6%96%AD%22%5D%0A%20%20S%20--%3E%20B%5B%22%E6%9C%9F%E6%9C%9B%E6%94%B6%E7%9B%8A%20%3D%20%E5%8D%B1%E6%9C%BA%E6%A6%82%E7%8E%87%20%C3%97%20%E8%9E%8D%E8%B5%84%E6%88%90%E6%9C%AC%E5%B7%AE%22%5D%0A%20%20B%20--%3E%20E%5B%22%E4%B8%8E%E6%9C%BA%E4%BC%9A%E6%88%90%E6%9C%AC%E6%89%93%E5%B9%B3%E5%A4%84%EF%BC%8C%E5%AE%9A%E6%9C%80%E4%BC%98%E4%BD%99%E9%A2%9D%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">代入数字感受这个权衡：设危机概率 10%，危机时外部融资比内源资金贵 30 个百分点，那么每多留 1 元现金的期望流动性收益约为 \\(0.1 \\times 0.3 = 3\\) 分/年；若现金利率比资金机会成本低正好 3 分/年，边际上打平——最优余额就停在附近。危机概率或成本差越大，账上越该厚。</span></p><p>与 LBO：PE 故意把现金掏空加杠杆，反 Jensen；成长 VC 企业现金是跑道，不是 FCF。样本继续决定理论。</p><h3 id="不要把现金-beta-当成安全资产课" tabindex="-1">不要把现金 beta 当成安全资产课 <a class="header-anchor" href="#不要把现金-beta-当成安全资产课" aria-label="Permalink to &quot;不要把现金 beta 当成安全资产课&quot;">​</a></h3><p>公司现金不是宏观安全资产便利收益的对象。本课是企业流动性管理。量化栏与宏观课序已有安全资产；此处不重写。</p><p><span class="marginnote">Opler, Pinkowitz, Stulz, Williamson, <em>JFE</em> 1999。Keynes 预防性动机是家庭货币需求；企业版换成投资与发行成本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成现金管理运营。下一课 ESG：目标函数若含非股东利益相关者，现金与对冲的「最优」会改——可能是约束或偏好。家族金字塔则改变现金在集团内的位置（隧道）。</p><p><span class="marginnote">常见误区：以为现金越多公司越安全。对成熟低增长企业，厚现金层往往是代理问题的温床——经理可以拿它做低回报并购而不受市场惩罚，市场反而给折价。现金是保险也是弹药：有增长机会、融资受限时它是救命钱；没有好项目又管不住手时，它是浪费的原料。</span></p><p>后课默认：现金是预防性保险加代理弹药；约束企业敏感性高。对冲与额度是替代，危机中不完全替代。项目使用现金有机会成本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预防性现金避免昂贵外部融资与投资中断；FCF 企业则是代理成本。</li><li>对冲、额度、现金部分替代；危机中额度与市值窗口不可靠。</li><li>被动积累与主动预防观测相似，识别在后。</li><li>出处：Opler et al., <em>JFE</em> 1999；Almeida, Campello and Weisbach, <em>JF</em> 2004。</li></ul>',11))])}const _=r(d,[["render",m]]);export{f as __pageData,_ as default};
